// `name` (one of docs/screen-document.md's weather icon names, or the two card-3 names
// hb_ui.h picks itself, "raindrop" and "umbrella") and `size` (28 or 24) to the
// descriptor to draw; nullptr when hb draws nothing under that name, or at that size.
inline const lv_image_dsc_t *icon(const char *name, int size) {
  if (name == nullptr || name[0] == '\0') return nullptr;
  if (strcmp(name, "sun") == 0) {
    if (size == 28) return &ICON_sun_28;
    if (size == 24) return &ICON_sun_24;
    return nullptr;
  }
  else if (strcmp(name, "night") == 0) {
    if (size == 28) return &ICON_night_28;
    if (size == 24) return &ICON_night_24;
    return nullptr;
  }
  else if (strcmp(name, "partly") == 0) {
    if (size == 28) return &ICON_partly_28;
    if (size == 24) return &ICON_partly_24;
    return nullptr;
  }
  else if (strcmp(name, "cloud") == 0) {
    if (size == 28) return &ICON_cloud_28;
    if (size == 24) return &ICON_cloud_24;
    return nullptr;
  }
  else if (strcmp(name, "rain") == 0) {
    if (size == 28) return &ICON_rain_28;
    if (size == 24) return &ICON_rain_24;
    return nullptr;
  }
  else if (strcmp(name, "pour") == 0) {
    if (size == 28) return &ICON_pour_28;
    if (size == 24) return &ICON_pour_24;
    return nullptr;
  }
  else if (strcmp(name, "snow") == 0) {
    if (size == 28) return &ICON_snow_28;
    if (size == 24) return &ICON_snow_24;
    return nullptr;
  }
  else if (strcmp(name, "fog") == 0) {
    if (size == 28) return &ICON_fog_28;
    if (size == 24) return &ICON_fog_24;
    return nullptr;
  }
  else if (strcmp(name, "storm") == 0) {
    if (size == 28) return &ICON_storm_28;
    if (size == 24) return &ICON_storm_24;
    return nullptr;
  }
  else if (strcmp(name, "wind") == 0) {
    if (size == 28) return &ICON_wind_28;
    if (size == 24) return &ICON_wind_24;
    return nullptr;
  }
  else if (strcmp(name, "raindrop") == 0) {
    if (size == 28) return &ICON_raindrop_28;
    if (size == 24) return &ICON_raindrop_24;
    return nullptr;
  }
  else if (strcmp(name, "umbrella") == 0) {
    if (size == 28) return &ICON_umbrella_28;
    if (size == 24) return &ICON_umbrella_24;
    return nullptr;
  }
  return nullptr;
}

